mapper.select:
SELECT p.post_id, p.board_type_code, p.title, p.category_code, COALESCE(p.contents_html, p.contents, '') AS contents, p.contents_html, p.contents_json, p.contents_text, p.writer_id, p.writer_name, la.profile_image AS writer_profile_image, p.last_modified_by, p.last_modified_by_name, p.view_count, p.is_pinned, p.login_popup_yn, p.popup_end_date, p.is_deleted, p.created_at, p.updated_at, COALESCE(( SELECT COUNT(*) FROM tb_common_file bf WHERE bf.tenant_id = #{tenantId} AND bf.owner_type = 'NOTICE' AND bf.owner_id = p.post_id AND bf.deleted_yn = 'N' ), 0) AS attachment_count FROM tb_board_post p LEFT JOIN public.tb_login_account la ON la.tenant_id = p.tenant_id AND la.login_code = p.writer_id WHERE p.tenant_id = #{tenantId} AND p.board_type_code = #{boardTypeCode} AND p.is_deleted = 'N'
AND ( p.title ILIKE '%' || #{keyword} || '%' OR p.writer_name ILIKE '%' || #{keyword} || '%' OR p.contents_text ILIKE '%' || #{keyword} || '%' )
AND p.category_code = #{noticeGubunCode}
AND p.is_pinned = #{isPinned}
ORDER BY p.created_at DESC, p.post_id DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*)
FROM tb_board_post p
WHERE p.tenant_id = #{tenantId}
  AND p.board_type_code = #{boardTypeCode}
  AND p.is_deleted = 'N'

  AND (
      p.title ILIKE '%' || #{keyword} || '%'
      OR p.writer_name ILIKE '%' || #{keyword} || '%'
      OR p.contents_text ILIKE '%' || #{keyword} || '%'
  )


    AND p.category_code = #{noticeGubunCode}


    AND p.is_pinned = #{isPinned}

SELECT login_id
FROM tb_login_account
WHERE tenant_id = #{tenantId}
  AND login_code = #{loginCode}
  AND use_at = 'Y'

mapper.update:
UPDATE tb_board_post
SET view_count = view_count + 1
WHERE tenant_id = #{tenantId}
  AND post_id = #{postId}
  AND board_type_code = #{boardTypeCode}
  AND is_deleted = 'N'

UPDATE tb_board_post
SET is_pinned = #{isPinned},
    last_modified_by = #{lastModifiedBy},
    last_modified_by_name = #{lastModifiedByName},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND post_id = #{postId}
  AND board_type_code = #{boardTypeCode}
  AND is_deleted = 'N'

UPDATE tb_board_post
SET is_deleted = 'Y',
    last_modified_by = #{lastModifiedBy},
    last_modified_by_name = #{lastModifiedByName},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND post_id = #{postId}
  AND board_type_code = #{boardTypeCode}

UPDATE tb_common_file
SET deleted_yn = 'Y',
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND file_id = #{boardFileId}
